<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
require_login();

function make_slug(string $title): string { $slug = strtolower(trim(preg_replace('/[^a-z0-9]+/i', '-', $title), '-')); return $slug ?: 'article'; }
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: null;
$editing = ['id'=>'','title'=>'','slug'=>'','category'=>'','excerpt'=>'','body'=>'','image_path'=>'','status'=>'draft','published_at'=>''];
if ($id) { $query = db()->prepare('SELECT * FROM articles WHERE id = ?'); $query->execute([$id]); $editing = $query->fetch() ?: $editing; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? '';
    if ($action === 'delete') { db()->prepare('DELETE FROM articles WHERE id = ?')->execute([(int)$_POST['id']]); flash('notice','Article removed.'); redirect('articles.php'); }
    $title=trim((string)$_POST['title']); $slug=make_slug(trim((string)$_POST['slug']) ?: $title); $status=$_POST['status']==='published' ? 'published' : 'draft';
    if ($title === '' || trim((string)$_POST['category']) === '' || trim((string)$_POST['excerpt']) === '' || trim((string)$_POST['body']) === '') { flash('notice','Title, category, excerpt and body are required.'); redirect('articles.php' . ($id ? '?id='.$id : '')); }
    $values=[$title,$slug,trim((string)$_POST['category']),trim((string)$_POST['excerpt']),trim((string)$_POST['body']),trim((string)$_POST['image_path']) ?: null,$status,$status==='published' ? date('Y-m-d H:i:s') : null];
    try { if ($id) { $values[]=$id; db()->prepare('UPDATE articles SET title=?,slug=?,category=?,excerpt=?,body=?,image_path=?,status=?,published_at=COALESCE(published_at, ?) WHERE id=?')->execute($values); flash('notice','Article updated.'); } else { db()->prepare('INSERT INTO articles (title,slug,category,excerpt,body,image_path,status,published_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')->execute($values); flash('notice','Article created.'); } } catch (PDOException $exception) { flash('notice','The slug is already in use. Choose a different slug.'); redirect('articles.php' . ($id ? '?id='.$id : '')); }
    redirect('articles.php');
}
$articles=db()->query('SELECT * FROM articles ORDER BY created_at DESC')->fetchAll(); $pageTitle=$id?'Edit insight':'Insights'; $activePage='articles'; require __DIR__.'/partials/header.php';
?>
<section class="panel"><h2><?= $id ? 'Update insight article' : 'Create insight article' ?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Title<input name="title" value="<?= e($editing['title']) ?>" required></label><label>URL slug<input name="slug" value="<?= e($editing['slug']) ?>" placeholder="generated-from-title"></label><label>Category<input name="category" value="<?= e($editing['category']) ?>" placeholder="PROPERTY MARKET INSIGHTS" required></label><label>Status<select name="status"><option value="draft" <?= $editing['status']==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $editing['status']==='published'?'selected':'' ?>>Published</option></select></label><label class="full">Summary / excerpt<textarea name="excerpt" required><?= e($editing['excerpt']) ?></textarea></label><label class="full">Article body<textarea name="body" required><?= e($editing['body']) ?></textarea></label><label class="full">Cover image path<input name="image_path" value="<?= e($editing['image_path']) ?>" placeholder="assets/buildings/image.jpg"></label><div class="form-actions full"><button class="button" type="submit">Save article</button><?php if($id): ?><a href="articles.php">Cancel</a><?php endif; ?></div></form></section>
<section class="panel"><h2>All articles</h2><?php if(!$articles): ?><p class="empty">No insight articles have been added yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Article</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($articles as $article): ?><tr><td><strong><?= e($article['title']) ?></strong><br><span class="hint"><?= e($article['category']) ?></span></td><td><span class="tag <?= $article['status']==='draft'?'draft':'' ?>"><?= e(ucfirst($article['status'])) ?></span></td><td><?= e($article['updated_at']) ?></td><td><a href="articles.php?id=<?= $article['id'] ?>">Edit</a> · <form class="inline-form" method="post" onsubmit="return confirm('Remove this article?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $article['id'] ?>"><button type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/partials/footer.php';
